48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const quote = (step: QuoteStep): number => {
52	  const base = step.items.length * 100;
53	  return base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
54	};
55	
56	export const runScenario = (scenario: Scenario): ScenarioResult => ({
57	  results: scenario.steps.map((step) => ({ premium: quote(step as QuoteStep) })),
58	});
